(()=>{'use strict';
const D=window.KOVA_DATA,A=window.KOVA_ARTWORK||[],$=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupees=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
$('#research-notes').innerHTML=D.sources.slice(0,2).map(s=>`<article><div><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><small>Observed ${esc(s.observed)}</small></div><p><b>Observed:</b> ${esc(s.observation)}</p><p><b>Our decision:</b> ${esc(s.inference)}</p><small>${esc(s.limit)}</small></article>`).join('');
function creatives(filter='all'){const items=A.filter(a=>filter==='all'||a.kind===filter);$('#creative-grid').innerHTML=items.map(a=>`<button class="creative-card" data-art="${a.id}"><div class="art-image"><img loading="lazy" src="${a.file.replace('.svg','.png')}" alt="${esc(a.title)} — finished ${a.format} artwork"></div><div><span>${a.format}</span><h3>${esc(a.title)}</h3><b>View artwork ↗</b></div></button>`).join('');}
creatives();
document.querySelectorAll('[data-creative-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-creative-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});creatives(b.dataset.creativeFilter);}));
let previousFocus;$('#creative-grid').addEventListener('click',e=>{const card=e.target.closest('[data-art]');if(!card)return;const a=A.find(a=>a.id===card.dataset.art);previousFocus=card;$('#creative-detail').innerHTML=`<img src="${a.file.replace('.svg','.png')}" alt="${esc(a.title)}"><div><span class="eyebrow">${a.format}</span><h2 id="artwork-title">${esc(a.title)}</h2><p>${esc(a.caption)}</p><p><b>CTA:</b> ${esc(a.cta)}</p><p class="note">Original AI-assisted fictional campaign artwork. Story polls and stickers are proposed copy, not interactive platform elements.</p><a class="button" href="${a.file}" download>Download editable SVG ↓</a><a class="plain-link" style="display:block;width:max-content;margin-top:18px" href="${a.file.replace('.svg','.png')}" download>Download PNG ↓</a></div>`;$('#creative-dialog').showModal();});
$('#close-creative').addEventListener('click',()=>$('#creative-dialog').close());$('#creative-dialog').addEventListener('click',e=>{if(e.target===$('#creative-dialog'))$('#creative-dialog').close();});$('#creative-dialog').addEventListener('close',()=>previousFocus?.focus());
function calendar(channel='all'){$('#calendar-body').innerHTML=D.calendar.filter(p=>channel==='all'||p.channel===channel).map(p=>`<tr><td>${p.day}</td><td><b>${esc(p.channel)}</b><small>${esc(p.format)} · ${esc(p.goal)}</small></td><td><b>${esc(p.headline)}</b><p>${esc(p.caption)}</p></td><td>${esc(p.cta)}<small>${esc(p.asset)} · planned</small></td></tr>`).join('');}calendar();$('#calendar-filter').addEventListener('change',e=>calendar(e.target.value));
$('#reel-grid').innerHTML=D.reels.map(r=>`<details><summary><span>${r.id} / ${r.length}</span><h3>${esc(r.title)}</h3></summary><p><b>Hook:</b> ${esc(r.hook)}</p><ul>${r.shots.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p><b>Voiceover:</b> ${esc(r.voiceover)}</p><p><b>CTA:</b> ${esc(r.cta)}</p><p class="note">${esc(r.production)}</p></details>`).join('');
function ads(){const g=$('#ad-group').value;$('#search-keywords').innerHTML=D.keywords.filter(k=>k.group===g&&k.intent!=='Informational').map(k=>`<span>${esc(k.keyword)} <small>${esc(k.match)}</small></span>`).join('');$('#rsa-assets').innerHTML=D.rsas.filter(a=>a.ad_group===g).map(a=>`<div class="rsa-row"><small>${a.asset_type} ${a.position}</small><span>${esc(a.text)}</span><b>${a.characters}/${a.limit}</b></div>`).join('');}ads();$('#ad-group').addEventListener('change',ads);$('#negatives').innerHTML=D.negatives.map(n=>`<span>${esc(n)}</span>`).join('');
const sum=k=>D.scenario.reduce((n,r)=>n+r[k],0),spend=sum('spend_inr'),leads=sum('demo_leads');
$('#metrics').innerHTML=[['Media spend',rupees(spend),'synthetic total'],['Demo leads',leads,'synthetic count'],['Cost per lead',rupees(spend/leads),'spend ÷ leads'],['Goal gap',`${60-leads} leads`,'below the planning goal']].map(([a,b,c])=>`<div><span>${a}</span><strong>${b}</strong><small>${c}</small></div>`).join('');
$('#funnel-body').innerHTML=D.scenario.map(r=>`<tr><td>${esc(r.channel)}</td><td>${rupees(r.spend_inr)}</td><td>${r.impressions.toLocaleString('en-IN')}</td><td>${r.clicks}</td><td>${r.landing_sessions}</td><td>${r.demo_leads}</td><td>${(r.clicks/r.impressions*100).toFixed(1)}%</td><td>${(r.demo_leads/r.landing_sessions*100).toFixed(2)}%</td><td>${rupees(r.spend_inr/r.demo_leads)}</td></tr>`).join('');
function scenario(e){e?.preventDefault();const budget=Number($('#budget').value),cpc=Number($('#cpc').value),sessions=Number($('#session-rate').value)/100,rate=Number($('#lead-rate').value)/100;if(!$('#scenario-form').reportValidity())return;const clicks=budget/cpc,leads=clicks*sessions*rate;$('#scenario-output').textContent=`${Math.round(clicks).toLocaleString('en-IN')} clicks → ${Math.round(clicks*sessions).toLocaleString('en-IN')} sessions → ${leads.toFixed(1)} expected leads under these assumptions. Implied CPL: ${leads>0?rupees(budget/leads):'not defined'}.`;}$('#scenario-form').addEventListener('submit',scenario);scenario();
function utm(e){e?.preventDefault();if(!$('#utm-form').reportValidity())return;const url=new URL('drop.html',location.href);for(const k of ['source','medium','campaign','content'])url.searchParams.set('utm_'+k,$('#utm-'+k).value);$('#utm-output').textContent=url.href;$('#utm-test').href=url.href;}$('#utm-form').addEventListener('submit',utm);utm();
function events(){try{const rows=JSON.parse(localStorage.getItem('kova_marketing_demo_events_v1')||'[]');$('#event-log').innerHTML=Array.isArray(rows)&&rows.length?rows.slice(-12).reverse().map(r=>`<div><b>${esc(r.event)}</b><span>${esc(r.time)}<small>${esc(Object.entries(r).filter(([k])=>!['event','time'].includes(k)).map(([k,v])=>`${k}: ${v}`).join(' · '))}</small></span></div>`).join(''):'<p class="empty">No test events in this browser yet. Try the landing page, then return here.</p>';}catch{$('#event-log').textContent='Local event storage is unavailable in this browser.';}}events();$('#refresh-events').addEventListener('click',events);$('#clear-events').addEventListener('click',()=>{try{localStorage.removeItem('kova_marketing_demo_events_v1');}catch{}events();});window.addEventListener('focus',events);window.addEventListener('storage',events);
})();
